sections.content:
Row(
mainAxisAlignment: MainAxisAlignment.spaceBetween,
children: const [
Text('Левый'),
Text('Правый'),
],
)

Row(
mainAxisAlignment: MainAxisAlignment.center,
children: const [
Text('Центр'),
],
)

// Row занимает всю ширину (children выровнены по центру)
Row(
mainAxisSize: MainAxisSize.max,
mainAxisAlignment: MainAxisAlignment.center,
children: const [Text('Центр')],
)

// Row занимает только пространство детей
Row(
mainAxisSize: MainAxisSize.min,
children: const [Text('Минимальная ширина')],
)

// Выравнивание по левому верхнему углу (по умолчанию)
Stack(
alignment: Alignment.topLeft,
children: [
Container(width: 200, height: 200, color: Colors.blue),
const Icon(Icons.star, size: 32, color: Colors.yellow),
],
)

// Выравнивание по центру
Stack(
alignment: Alignment.center,
children: [
Container(width: 200, height: 200, color: Colors.blue),
const Icon(Icons.star, size: 32, color: Colors.yellow),
],
)

// Выравнивание по правому нижнему углу
Stack(
alignment: Alignment.bottomRight,
children: [
Container(width: 200, height: 200, color: Colors.blue),
const Icon(Icons.favorite, size: 24, color: Colors.red),
],
)

Container(
decoration: BoxDecoration(
color: Colors.white,
borderRadius: BorderRadius.circular(12),
boxShadow: [
BoxShadow(
color: Colors.black.withOpacity(0.1),
blurRadius: 8,
),
],
),
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Stack(
children: [
Image.asset(
'assets/images/product.jpg',
height: 160,
width: double.infinity,
fit: BoxFit.cover,
),
Positioned(
top: 8,
right: 8,
child: Container(
padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
decoration: BoxDecoration(
color: Colors.red,
borderRadius: BorderRadius.circular(4),
),
child: const Text(
'-20%',
style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold),
),
),
),
],
),
Padding(
padding: const EdgeInsets.all(12),
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
const Text(
'Название товара',
style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
),
const SizedBox(height: 4),
Row(
mainAxisAlignment: MainAxisAlignment.spaceBetween,
children: [
const Text(
'1 200 ₽',
style: TextStyle(fontSize: 18, color: Colors.blue),
),
const Icon(Icons.favorite_border, color: Colors.grey),
],
),
],
),
),
],
),
)

LayoutBuilder(
builder: (context, constraints) {
if (constraints.maxWidth > 600) {
return Row(children: [...]);
}
return Column(children: [...]);
},
)
